H.background();
const a1 = P.a1, r = P.r, nMax = Math.max(2, Math.round(P.n));
const partial = (m) => Math.abs(r - 1) < 1e-9 ? a1 * m : a1 * (1 - Math.pow(r, m)) / (1 - r);
let yHi = 1;
for (let m = 1; m <= nMax; m++) yHi = Math.max(yHi, Math.abs(partial(m)));
const v = H.plot2d({ xMin: 0, xMax: nMax + 1, yMin: Math.min(0, -yHi * 0.2), yMax: yHi * 1.2 });
v.grid(); v.axes();
const shown = 1 + Math.floor((t * 0.9) % nMax);
for (let m = 1; m <= nMax; m++) {
  const s = partial(m);
  const lit = m <= shown;
  v.rect(m - 0.4, 0, 0.8, s, { fill: lit ? H.colors.accent : H.colors.panel, stroke: H.colors.accent, width: 1.5 });
}
let limTxt = "";
if (Math.abs(r) < 1) {
  const lim = a1 / (1 - r);
  v.line(0, lim, nMax + 1, lim, { color: H.colors.violet, width: 2, dash: [6, 5] });
  limTxt = "   -> converges to a_1/(1-r) = " + lim.toFixed(2);
} else {
  limTxt = "   |r|>=1: diverges";
}
v.circle(shown, partial(shown) / 2, 6 + 2 * Math.sin(t * 4), { fill: H.colors.warn });
H.text("Geometric series:  S_n = a_1(1 - r^n)/(1 - r)", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
H.text("S_" + shown + " = " + partial(shown).toFixed(2) + limTxt, 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "partial sum S_n", color: H.colors.accent }, { label: "limit a_1/(1-r)", color: H.colors.violet }], H.W - 210, 28);
